-- Terms and categories from the real Google Maps test (20 industries x 5 terms x Austin, Atlanta, Phoenix; about 1,900
-- businesses). Terms: most businesses in the trade first, then the one adding the most new ones. Categories: every
-- category businesses in the trade carry (main or secondary), minus generic and other-trade ones. Overlapping industries removed.
INSERT INTO industries (name, terms, categories, position, created_at) SELECT 'Fence Installers', '[]', '[]', 16, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM industries WHERE name = 'Fence Installers');
